function parseJ(s, f) { try { const v = JSON.parse(s); return v == null ? f : v; } catch (e) { return f; } }

function readSettings(node) {
  const st = {};
  try { $(node).all().forEach(function (it) { if (it.json && it.json.key) st[it.json.key] = String(it.json.value == null ? '' : it.json.value); }); } catch (e) { /* defaults */ }
  return st;
}

const st = readSettings('Get Settings');
const names = {};
parseJ(st.calendars, []).forEach(function (c) { if (c && c.id) names[c.id] = c.name || c.id; });
const ids = [];
function add(id) { id = String(id || '').trim(); if (id && ids.indexOf(id) < 0) ids.push(id); }
const busy = parseJ(st.busyCalendars, null);
(Array.isArray(busy) && busy.length ? busy : ['primary', 'primary']).forEach(add);
let days = 0;
$('Start').all().forEach(function (it) {
  const j = it.json || {};
  String(j.extraCalendars || '').split(',').forEach(add);
  days = Math.max(days, Number(j.days) || 0);
});
days = Math.min(days || 76, 366);
const timeMax = DateTime.now().plus({ days: days }).toISO();
return ids.map(function (id) {
  return { json: { calendarId: id, calendarName: names[id] || (id === 'primary' ? 'Primary' : id), timeMax: timeMax }, pairedItem: { item: 0 } };
});

const out = [];
const listed = $('List Busy Calendars').all().map(function (it) { return it.json.calendarName; });
$input.all().forEach(function (it, i) {
  const j = it.json || {};
  let src = {};
  try { src = $('List Busy Calendars').itemMatching(i).json || {}; } catch (e) { src = {}; }
  if (j.error) {
    out.push({ json: { __calendarError: true, calendarId: src.calendarId || '', calendarName: src.calendarName || '',
      message: String((j.error && j.error.message) || j.error) } });
    return;
  }
  if (!j.start) return;
  out.push({ json: Object.assign({}, j, { __calendarId: src.calendarId || '', __calendarName: src.calendarName || '' }) });
});
out.push({ json: { __summary: true, calendars: listed } });
return out;
